<?php if($manageForms&&$sections):?><details class="inline-builder question-builder" open><summary>+ Add an applicant question</summary><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/form-fields') ?>" data-field-builder data-key-builder><?= csrf_field() ?><div class="form-grid"><label><span>Form section</span><select name="section_id" required><?php foreach($sections as $section):?><option value="<?= e($section['id']) ?>"><?= e($section['title']) ?></option><?php endforeach?></select><small>Choose the group where this question belongs.</small></label><label><span>Question shown to applicants</span><input name="label" required data-key-source placeholder="Example: Do you require hostel accommodation?"></label><label><span>Answer type</span><select name="field_type" data-field-type><?php foreach($fieldTypeLabels as $type=>$typeLabel): if(in_array($type,['file','program_preferences'],true))continue;?><option value="<?= e($type) ?>"><?= e($typeLabel) ?></option><?php endforeach?></select></label><label><span>Example answer / placeholder</span><input name="placeholder"></label><label class="full"><span>Helpful instruction</span><input name="help_text" placeholder="Optional guidance shown below the question"></label><label class="decision-option"><input type="checkbox" name="is_required" value="1" checked><span><b>Applicants must answer this question</b><small>Clear this if the answer is optional.</small></span></label><label class="full field-options-panel" data-field-options><span>Answer choices</span><textarea name="options" rows="4" placeholder="Yes&#10;No"></textarea><small>Needed only for dropdown, choice, checkbox or multi-select questions. Enter one choice per line.</small></label></div><details class="advanced-options"><summary>Advanced field settings</summary><div class="form-grid"><label><span>Internal field key (optional)</span><input name="field_key" data-key-target placeholder="Created from the question automatically"></label><label><span>Display order</span><input type="number" name="sort_order" value="100"></label><label><span>Built-in data connection</span><input name="canonical_binding" placeholder="Leave blank for a custom question"></label><label class="full"><span>Show only when (JSON)</span><textarea name="conditional_rules" placeholder='{"field":"category","operator":"eq","value":"SC"}'></textarea></label><label class="check-control"><input type="checkbox" name="is_searchable" value="1"><span>Allow staff search/filter use</span></label></div></details><button class="button button-primary">Add question</button></form></details><?php endif?>
