<section class="card wizard-panel" id="documents" data-section-panel><div class="workspace-section-heading"><div><span class="eyebrow">Step 6 of 7</span><h2>Choose required documents</h2><p>Define the evidence applicants must upload and keep admission-stage documents separate from application-stage requirements.</p></div><span class="status-pill status-<?= $documentsComplete?'verified':'rejected' ?>"><?= $documentsComplete?'Complete':'Required document needed' ?></span></div><div class="step-guide compact-guide"><div><i>1</i><span><b>Choose the document</b><small>Select the evidence applicants must provide.</small></span></div><div><i>2</i><span><b>Choose when it is needed</b><small>Application stage is uploaded before submission; admission stage is collected later.</small></span></div><div><i>3</i><span><b>Limit only when necessary</b><small>Leave programme and category as “All” unless the requirement is specific.</small></span></div></div><div class="editable-record-list document-records"><?php foreach($requirements as $requirement):?><details class="editable-record"><summary><div><b><?= e($requirement['name']) ?></b><small><?= e($requirement['program_name']?:'All programmes') ?> · <?= e($requirement['category']?:'All categories') ?> · <?= e($requirement['stage']) ?> · <?= $requirement['is_required']?'required':'optional' ?></small></div><span>Edit</span></summary><?php if($manageDocuments):?><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/documents') ?>"><?= csrf_field() ?><input type="hidden" name="requirement_id" value="<?= e($requirement['id']) ?>"><div class="form-grid three"><label><span>Document type</span><select name="document_type_id" required><?php foreach($documentTypes as $type):?><option value="<?= e($type['id']) ?>"<?= selected($requirement['document_type_id'],$type['id']) ?>><?= e($type['name']) ?></option><?php endforeach?></select></label><label><span>Programme scope</span><select name="program_id"><option value="">All programmes</option><?php foreach($programs as $program):?><option value="<?= e($program['program_id']) ?>"<?= selected($requirement['program_id'],$program['program_id']) ?>><?= e($program['name']) ?></option><?php endforeach?></select></label><label><span>Category scope</span><select name="category"><option value="">All categories</option><?php foreach($categories as $category):?><option value="<?= e($category['code']) ?>"<?= selected($requirement['category'],$category['code']) ?>><?= e($category['name']) ?></option><?php endforeach?></select></label><label><span>Stage</span><select name="stage"><option value="application"<?= selected($requirement['stage'],'application') ?>>Application — before submission</option><option value="admission"<?= selected($requirement['stage'],'admission') ?>>Admission — after selection</option></select></label><label><span>Display order</span><input type="number" name="sort_order" value="<?= e($requirement['sort_order']) ?>"></label><label class="check-control"><input type="checkbox" name="is_required" value="1" <?= checked($requirement['is_required']) ?>><span>Required</span></label></div><button class="button button-outline">Update requirement</button></form><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/documents/'.$requirement['id'].'/delete') ?>"><?= csrf_field() ?><button class="text-button danger" data-confirm="Delete this unused document requirement?">Delete requirement</button></form><?php endif?></details><?php endforeach?></div><?php if($manageDocuments):?><details class="inline-builder"><summary>+ Add document requirement</summary><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/documents') ?>"><?= csrf_field() ?><div class="form-grid three"><label><span>Document type</span><select name="document_type_id" required><?php foreach($documentTypes as $type):?><option value="<?= e($type['id']) ?>"><?= e($type['name']) ?></option><?php endforeach?></select></label><label><span>Programme scope</span><select name="program_id"><option value="">All programmes</option><?php foreach($programs as $program):?><option value="<?= e($program['program_id']) ?>"><?= e($program['name']) ?></option><?php endforeach?></select></label><label><span>Category scope</span><select name="category"><option value="">All categories</option><?php foreach($categories as $category):?><option value="<?= e($category['code']) ?>"><?= e($category['name']) ?></option><?php endforeach?></select></label><label><span>Stage</span><select name="stage"><option value="application">Application — before submission</option><option value="admission">Admission — after selection</option></select></label><label><span>Display order</span><input type="number" name="sort_order" value="100"></label><label class="check-control"><input type="checkbox" name="is_required" value="1" checked><span>Required for applicants</span></label></div><button class="button button-primary">Add requirement</button></form></details><?php endif?><div class="wizard-panel-actions"><a class="button button-outline" href="#form-builder">← Application form</a><a class="button button-primary" href="#review-publish">Continue: Review & publish →</a></div></section>

<section class="card wizard-panel review-publish-panel" id="review-publish" data-section-panel><div class="workspace-section-heading"><div><span class="eyebrow">Step 7 of 7</span><h2>Review and publish the admission notice</h2><p>Check every section, open the public preview, then publish one immutable configuration version.</p></div><span class="status-pill status-<?= $readiness['ready']?'verified':'rejected' ?>"><?= $readiness['ready']?'Ready to publish':'Action required' ?></span></div>
