<div class="publish-decision"><div><span class="eyebrow">What publication does</span><h3>Make this admission cycle visible to applicants</h3><p>Publishing freezes this configuration as a versioned snapshot. Applicants will see its public summary, dates, programmes, fees, document requirements, instructions and prospectus on the Admissions page.</p></div><div class="publish-decision-actions"><a class="button button-outline" target="_blank" href="<?= url('admin/admissions/'.$cycle['id'].'/preview') ?>">Open public preview ↗</a><?php if($draft&&can('admissions.publish')):?><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/publish') ?>"><?= csrf_field() ?><button class="button button-primary" data-confirm="Publish this admission notice and freeze configuration version <?= (int)$cycle['configuration_version']+1 ?>?" <?= !$readiness['ready']?'disabled':'' ?>>Publish admission notice</button></form><?php elseif(!$draft):?><span class="published-confirmation">✓ Published configuration v<?= e($cycle['configuration_version']) ?></span><?php endif?></div></div>
<details class="post-publication-details"><summary>Configuration version history</summary><?php if(!$versions):?><p>No published version yet.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Version</th><th>Status</th><th>Hash</th><th>Published by</th><th>Time</th></tr></thead><tbody><?php foreach($versions as $version):?><tr><td><b>v<?= e($version['version_no']) ?></b></td><td><?= e($version['status']) ?></td><td><code><?= e(substr($version['snapshot_hash'],0,18)) ?>…</code></td><td><?= e($version['creator_name']?:'System migration') ?></td><td><?= format_date($version['created_at'],true) ?></td></tr><?php endforeach?></tbody></table></div><?php endif?></details>
